function wrongList(attempt, key) {
  let wrong = [];
  for (let i = 0; i < key.length; i++) {
    if (attempt[i] != key[i]) {
      wrong.push(i + 1);
    }
  }
  return wrong;
}

function average(score) {
  if (score.length == 0) {
    return 0;
  }
  let total = 0;
  for (let i = 0; i < score.length; i++) {
    total += score[i];
  }
  return total / score.length;
}

function check(g, lower, upper, secret) {
  g = Number(g);
  lower = Number(lower);
  upper = Number(upper);
  if (g <= lower || g >= upper) {
    return "Invalid";
  } else if (g == secret) {
    return "Correct";
  } else if (g > secret) {
    return "Too high";
  } else {
    return "Too low";
  }
}

function nextValue(text, k) {
  let x = Number(text) + k;
  if (x < 0) {
    return Number(text);
  }
  return x;
}
